.faq-wrapper{background-color:#f2f2f2;margin:0;padding:8rem 0 6rem}.faq-wrapper h2.section-heading{margin-bottom:2rem}.faq-section{display:flex;max-width:1250px;margin:0 auto;background-color:#f2f2f2;padding:20px;border-radius:8px}.faq-questions{width:70%;background-color:#fff}.faq-item{padding:1px 15px;cursor:pointer;transition:background .3s ease;border-bottom:1px solid #ccc}.faq-item:hover{background-color:#e6e6e6}.faq-item.active{background-color:#f2f2f2;border-right:3px solid #a5221e}.faq-item h3.faq-question{font-weight:400}.active h3.faq-question{font-weight:500}.faq-answer-container{width:100%;padding-left:20px}.faq-answer{display:none;padding:0 15px;border-radius:8px}.faq-item.active+.faq-answer{display:block}.center-button{width:20rem;margin:2rem auto;text-align:center}.faq-section .desktop{display:block;width:65%}.faq-section .mobile{display:none}@media (max-width:768px){.faq-section .desktop{display:none}.faq-section .mobile{display:block}.faq-section{display:block}.faq-questions,.faq-answer-container{width:100%;padding:0}.faq-item{border-bottom:none;background-color:#f2f2f2}.faq-answer{display:none;padding:10px}.faq-item.active{background-color:#fff}.faq-item.active+.faq-answer{display:block}}